#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""Fill an HWPX (.hwpx) template by replacing {{key}} placeholders.

- Reads mapping from /root/inventory_data.json
- Finds XML files inside the HWPX zip that contain '{{'
- Performs replacement per paragraph (hp:p), so placeholders split across runs
  within a paragraph still get replaced.
- For any paragraph whose text changes, removes layout-cache elements such as
  hp:linesegarray / hp:lineSegArray to prevent stale layout rendering.
- Writes the updated package to /root/inventory_report_ready.hwpx
"""

from __future__ import annotations

import json
import re
import zipfile
from pathlib import Path
import xml.etree.ElementTree as ET


TEMPLATE_PATH = Path("/root/inventory_report_template.hwpx")
DATA_PATH = Path("/root/inventory_data.json")
OUT_PATH = Path("/root/inventory_report_ready.hwpx")

WORK_DIR = Path("/tmp/hwpx_work")
EXTRACT_DIR = WORK_DIR / "template_extracted"

HWPML_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"
NS = {"hp": HWPML_NS}
ET.register_namespace("hp", HWPML_NS)

PLACEHOLDER_RE = re.compile(r"\{\{([^{}]+)\}\}")


def load_mapping() -> dict[str, str]:
    data = json.loads(DATA_PATH.read_text(encoding="utf-8"))
    # Normalize everything to strings (HWPX text nodes are strings)
    mapping: dict[str, str] = {}
    for k, v in data.items():
        mapping[str(k)] = "" if v is None else str(v)
    return mapping


def localname(tag: str) -> str:
    if tag.startswith("{"):
        return tag.split("}", 1)[1]
    return tag


def paragraph_text_nodes(p_el: ET.Element) -> list[ET.Element]:
    # Collect hp:t elements in document order under this paragraph.
    return list(p_el.findall(".//hp:t", NS))


def join_text(nodes: list[ET.Element]) -> str:
    parts: list[str] = []
    for n in nodes:
        parts.append(n.text or "")
    return "".join(parts)


def replace_placeholders(text: str, mapping: dict[str, str]) -> tuple[str, set[str]]:
    used: set[str] = set()

    def _sub(m: re.Match[str]) -> str:
        key = m.group(1)
        if key in mapping:
            used.add(key)
            return mapping[key]
        # Unknown placeholder: leave as-is.
        return m.group(0)

    return PLACEHOLDER_RE.sub(_sub, text), used


def remove_layout_cache_children(p_el: ET.Element) -> None:
    # Only remove the layout-cache elements within this paragraph.
    # Observed in template: <hp:linesegarray> ...
    # Also handle common variants in other documents.
    cache_names = {
        "linesegarray",
        "lineSegArray",
        "linesegArray",
        "lineSeg",
        "lineseg",
    }

    # Only direct children should be removed (per instruction: "child elements"),
    # but be robust and remove any descendants matching cache names.
    for parent in list(p_el.iter()):
        for child in list(parent):
            if localname(child.tag) in cache_names:
                parent.remove(child)


def process_xml(xml_bytes: bytes, mapping: dict[str, str], zip_member: str) -> tuple[bytes, dict]:
    raw_text = xml_bytes.decode("utf-8")

    placeholders_in_file = sorted(set(PLACEHOLDER_RE.findall(raw_text)))
    missing = sorted([k for k in placeholders_in_file if k not in mapping])

    root = ET.fromstring(xml_bytes)

    changed_paragraphs = 0
    used_keys: set[str] = set()

    for p in root.findall(".//hp:p", NS):
        t_nodes = paragraph_text_nodes(p)
        if not t_nodes:
            continue

        original = join_text(t_nodes)
        # Preserve truly empty paragraphs: nothing to replace.
        if original == "":
            continue

        replaced, used = replace_placeholders(original, mapping)
        if replaced == original:
            continue

        used_keys |= used

        # Put the entire updated text into the first hp:t node,
        # and clear the rest to avoid split placeholders leaving remnants.
        t_nodes[0].text = replaced
        for n in t_nodes[1:]:
            n.text = ""

        remove_layout_cache_children(p)
        changed_paragraphs += 1

    out_bytes = ET.tostring(root, encoding="utf-8", xml_declaration=True)

    info = {
        "zip_member": zip_member,
        "placeholders_in_file": placeholders_in_file,
        "missing_placeholders": missing,
        "used_keys": sorted(used_keys),
        "changed_paragraphs": changed_paragraphs,
    }
    return out_bytes, info


def main() -> int:
    if not TEMPLATE_PATH.exists():
        raise SystemExit(f"Template not found: {TEMPLATE_PATH}")
    if not DATA_PATH.exists():
        raise SystemExit(f"Data JSON not found: {DATA_PATH}")

    mapping = load_mapping()

    # Read template zip and process in-memory.
    with zipfile.ZipFile(TEMPLATE_PATH, "r") as zin:
        members = zin.namelist()
        xml_targets: list[str] = []
        for m in members:
            # Only consider files; directory entries end with '/'
            if m.endswith("/"):
                continue
            try:
                data = zin.read(m)
            except KeyError:
                continue
            if b"{{" in data:
                xml_targets.append(m)

        reports = []

        with zipfile.ZipFile(OUT_PATH, "w", compression=zipfile.ZIP_DEFLATED) as zout:
            for m in members:
                if m.endswith("/"):
                    # Preserve directory entries if present
                    zout.writestr(m, b"")
                    continue

                data = zin.read(m)
                if m in xml_targets and m.lower().endswith(".xml"):
                    new_bytes, info = process_xml(data, mapping, m)
                    reports.append(info)
                    zout.writestr(m, new_bytes)
                else:
                    zout.writestr(m, data)

    # Basic mapping coverage report to stdout (for the harness logs).
    all_placeholders = sorted({p for r in reports for p in r["placeholders_in_file"]})
    missing_total = sorted({p for r in reports for p in r["missing_placeholders"]})

    print("Processed members containing placeholders:")
    for r in reports:
        print(
            f"- {r['zip_member']}: changed_paragraphs={r['changed_paragraphs']}, "
            f"placeholders={len(r['placeholders_in_file'])}, missing={len(r['missing_placeholders'])}"
        )

    if all_placeholders:
        print("\nPlaceholders seen in template:")
        for p in all_placeholders:
            print(f"  - {p}")
    else:
        print("\nNo placeholders found in the template.")

    if missing_total:
        print("\nWARNING: placeholders missing from JSON mapping (left unchanged):")
        for p in missing_total:
            print(f"  - {p}")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())

